# Manually reviewed primary abstracts; quantities are source-reported, never calculated.
ROWS=[]
def add(c,d,p,t,e,q='',dose='',pop='',mechanism='',outcome='observed effect',prep='Isolated named compound; formulation details not extracted',note='',affected='drug',perp='compound'):
 ROWS.append(dict(compound=c,drug=d,pmid=p,type=t,effect=e,quantity=q,dose=dose,population=pop,mechanism=mechanism,outcome=outcome,preparation=prep,note=note,affected=affected,perpetrator=perp))
for c in ['(+)-Catechin','(-)-Epicatechin']:
 add(c,'Paclitaxel','12920504','In vitro','No inhibition of paclitaxel metabolism detected in the tested rat and human liver microsomes.',pop='Rat and human liver microsomes',outcome='no inhibition detected',note='Null in these assays does not establish clinical absence of interaction.')
add('Morin','Paclitaxel','12920504','In vitro','Inhibited metabolism in human liver microsomes; no effect in rat microsomes.',pop='Rat and human liver microsomes',mechanism='Mixed-type inhibition generally reported across inhibitory phenolics; compound-specific kinetic detail not extracted',outcome='species-dependent inhibition')
